#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int y, capacity, flow, cost;
    Edge() {}
    Edge(int y, int c, int f, int cost) : y(y), capacity(c), flow(f), cost(cost) {}
};

vector<Edge> edges;
const int MAXN = 14043;
vector<int> graph[MAXN];

long long total_cost = 0;
long long dist[MAXN];
int parent[MAXN], parent_edge[MAXN], inq[MAXN];

const long long INF = 1e18;
int s = MAXN - 2;
int t = MAXN - 1;

int residual_capacity(int idx) {
    return edges[idx].capacity - edges[idx].flow;
}

void find_path_and_push_flow() {
    for (int i = 0; i < MAXN; i++) {
        dist[i] = INF;
        parent[i] = -1;
        parent_edge[i] = -1;
        inq[i] = 0;
    }
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    inq[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (auto e_idx : graph[u]) {
            if (residual_capacity(e_idx) == 0) continue;
            int y = edges[e_idx].y;
            int cst = edges[e_idx].cost;
            if (dist[y] > dist[u] + cst) {
                dist[y] = dist[u] + cst;
                parent[y] = u;
                parent_edge[y] = e_idx;
                if (!inq[y]) {
                    inq[y] = 1;
                    q.push(y);
                }
            }
        }
    }
    int node = t;
    while (node != s) {
        edges[parent_edge[node]].flow++;
        edges[parent_edge[node] ^ 1].flow--;
        node = parent[node];
    }
    total_cost += dist[t];
}

void connect_nodes(int from, int to, int cap, int cst) {
    graph[from].push_back(edges.size());
    edges.emplace_back(to, cap, 0, cst);
    graph[to].push_back(edges.size());
    edges.emplace_back(from, 0, 0, -cst);
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x; --x;
        connect_nodes(s, x, 1, 0);
    }
    int T = 101;
    for (int i = 0; i < T; i++)
        connect_nodes(i * n, t, k, i * c);
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y; --x; --y;
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                connect_nodes(x + i * n, y + i * n + n, 1, d * (j * 2 + 1));
            }
        }
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                connect_nodes(y + i * n, x + i * n + n, 1, d * (j * 2 + 1));
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < T - 1; j++) {
            connect_nodes(i + j * n, i + j * n + n, k, 0);
        }
    }
    for (int i = 0; i < k; i++) {
        find_path_and_push_flow();
    }
    cout << total_cost << endl;
}
